class Block {
    /**
     * 基础块
     * @param {*} applicator 施加该块的武将
     * @param {*} tactics 施加该块的战法
     * @param {*} duration 持续时间
     * @param {*} waitTime 该块生效的等待时间
     */
    constructor(applicator, tactics, duration, waitTime) {
        this.id = `${Date.now()}${Math.random().toString(36).substring(2, 8)}`;
        this.applicator = applicator;
        this.tactics = tactics;
        this.duration = duration;
        this.waitTime = waitTime == undefined ? 0 : waitTime;
        this.beExecuted = undefined;
        this.blockCreateTurn = applicator != undefined ? applicator.driver.turn : undefined;
        this.storageKey = ""; // 改为存储“数组名称字符串”（如"DODGE"），而非数组引用
        this.isDestroyed = false; // 新增：防止重复销毁
    }

    /**
     * 绑定目标和存储数组名称
     * @param {*} target 被施加的目标武将
     * @param {string} storageKey 目标身上的数组名称（如"DODGE"）
     */
    BindTarget(target, storageKey) {
        this.beExecuted = target;
        this.storageKey = storageKey; // 存数组名称（字符串），而非数组引用
    }

    /**
     * 自我销毁：直接操作目标的真实数组
     * @returns {boolean} true=找到并移除，false=销毁失败
     */
    SelfDestroy() {
        // 1. 前置校验：防止重复销毁/核心属性缺失
        if (this.isDestroyed) {
            console.warn(`块${this.id}已销毁，无需重复操作`);
            return false;
        }
        if (!this.beExecuted || !this.storageKey) {
            console.error(`块${this.id}销毁失败：目标或存储数组名称未绑定`);
            return false;
        }
        let targetArray = this.beExecuted[this.storageKey]; // 直接获取目标的真实数组
        if (!Array.isArray(targetArray)) {
            console.error(`块${this.id}销毁失败：目标的${this.storageKey}不是数组`);
            return false;
        }

        // 2. 核心逻辑：过滤移除自身（用id匹配，比引用更可靠）
        let res = false;
        let remain = [];
        targetArray.forEach(block => {
            if (block.id !== this.id) { // 用唯一id匹配，避免引用比较的坑
                remain.push(block);
            } else {
                res = true; // 标记找到自身
            }
        });

        // 3. 直接修改目标的真实数组（关键！）
        this.beExecuted[this.storageKey] = remain;
        this.isDestroyed = true; // 标记已销毁

        return res;
    }
}

// ------------------------- 规避 --------------------------------------------------
export class DodgeBlock extends Block {
    constructor(applicator, tactics, duration, rate) {
        super(applicator, tactics, duration, 0)
        //触发规避的几率
        this.rate = rate == undefined ? 120 : rate;
    }
    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        let abort = target.DODGE.some(block => {
            //同一个战法施加的规避可以重复
            if (block.tactics.type == this.tactics.type && block.tactics != this.tactics) {
                let report = new Report();
                report.InitExecuteReport(reportLevel, target, `已存在规避效果`);
                return true;
            }
        })
        //移除其他战法提供的规避
        let remain = [];
        target.DODGE.forEach(block => {
            if (block.tactics == this.tactics) remain.push(block);
        });
        target.DODGE = remain;
        if (abort) return false;
        super.BindTarget(target, "DODGE")
        target.DODGE.push(this);
        if (needReport) {
            let msg = `规避效果已施加`
            if (this.rate >= 100) msg = `规避(预备)效果已施加`
            let r = new Report();
            if (reportStyle == 1) r.InitExecuteReport(reportLevel, target, msg);
            if (reportStyle == 2) r.InitTwoTargetReport(reportLevel, this.applicator, target, `【${this.tactics.name}】令`, `规避${this.rate >= 100 ? "" : "(预备)"}下一次伤害`);
        }
        return true;
    }
}

