// ------------------------- 特殊攻击块（反击块） --------------------------------------------------
export class CounterAttackBlock extends Block {
    /**
     * 特殊攻击块（反击）
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} type 攻击类型（如"反击"）
     * @param {*} damageValue 伤害率
     * @param {*} rate 触发率
     * @param {*} duration 持续时间
     * @param {*} waitTime 等待时间
     */
    constructor(applicator, tactics, type, damageValue, rate, duration, waitTime) {
        // 调用父类构造函数初始化通用属性
        super(applicator, tactics, duration, waitTime);
        // 子类自有属性
        this.type = type; // 攻击类型
        this.damageValue = damageValue; // 伤害率
        this.rate = rate; // 触发率
    }

    /**
     * 初始化反击块
     * @param {*} target 目标武将
     * @param {*} needReport 是否生成战报
     * @param {*} reportLevel 战报等级
     * @param {*} reportStyle 战报样式
     * @returns 
     */
    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        // 绑定目标和存储数组
        super.BindTarget(target, "SPEC_ATTACK");

        // 冲突检测
        let abort = target.SPEC_ATTACK.some(block => block.type === this.type);
        if (abort) {
            let r = new Report();
            r.InitExecuteReport(3, target, `已存在${this.type}效果`);
            return false;
        }

        // 添加到目标数组
        target.SPEC_ATTACK.push(this);

        // 生成战报
        if (needReport) {
            this.InitReport(reportStyle, reportLevel);
        }
        return true;
    }

    /**
     * 重写战报方法：反击块专属战报
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null) {
        let r = new Report();
        let msg = `获得${this.type}能力`;

        if (reportStyle === 1) {
            r.InitExecuteReport(reportLevel, this.beExecuted, msg);
        }
        if (reportStyle === 2) {
            r.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】令`, msg);
        }
        if (reportStyle === 3) {
            let r = new Report("状态信息");
            r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}效果消失了`);
        }
        if (reportStyle === 4) {
            r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}效果被移除了`);
        }
        if (reportStyle === 4 && newApplicator && newTact) {
            r.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, `${this.type}效果`);
        }
    }
}

// ------------------------- 属性块 --------------------------------------------------
export class AttrBlock extends Block {
    /**
     * 属性块
     * @param {object} applicator 施加者
     * @param {object} tactics 来源战法
     * @param {string} attrType 属性类型（攻击/谋略/防御/速度）
     * @param {number} value 数值
     * @param {number} duration 持续时间
     * @param {boolean} isRepeat 是否可叠加
     * @param {boolean} isBenefit 是否增益
     */
    constructor(applicator, tactics, attrType, value, duration, isRepeat, isBenefit) {
        // 调用父类构造函数（waitTime默认0）
        super(applicator, tactics, duration, 0);
        // 子类自有属性
        this.attrType = attrType; // 属性类型
        this.value = value; // 属性值
        this.isRepeat = isRepeat == undefined ? false : isRepeat; // 是否可叠加（默认不可）
        this.isBenefit = isBenefit ?? (this.value >= 0); // 是否增益（默认按数值正负）
        this.owner = null; // 兼容原有命名（和beExecuted指向同一目标）
    }

    /**
     * 初始化属性块
     * @param {object} target 目标武将
     * @param {boolean} needReport 是否生成战报
     * @param {number} reportLevel 战报等级
     * @param {number} reportStyle 战报样式
     * @returns 
     */
    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        // 绑定目标和存储数组
        super.BindTarget(target, "ATTR");
        this.owner = target;
        // 是否叠加逻辑
        let doRepeat = false;
        if (this.isRepeat) {
            target.ATTR.forEach(block => {
                if (block.tactics === this.tactics && block.attrType === this.attrType && block.isRepeat) {
                    // 叠加数值并刷新持续时间
                    block.value += this.value;
                    block.duration = this.duration;
                    this.value = block.value
                    doRepeat = true;
                }
            });
        }

        // 冲突检测（仅当不叠加时执行）
        let abort = false;
        if (!doRepeat) {
            let remain = [];
            abort = target.ATTR.some(block => {
                if (block.attrType === this.attrType && this.tactics.type === block.tactics.type) {
                    // 增益属性冲突
                    if (this.isBenefit && block.isBenefit) {
                        if (this.value <= block.value) {
                            let report = new Report();
                            report.InitExecuteReport(reportLevel, target, `已存在更强的${block.attrType}属性提升效果`);
                            return true;
                        } 
                    }
                    // 减益属性冲突
                    else if (!this.isBenefit && !block.isBenefit) {
                        if (this.value >= block.value) {
                            let report = new Report();
                            report.InitExecuteReport(reportLevel, target, `已存在更强的${block.attrType}属性降低效果`);
                            return true;
                        } 
                    } else {
                        remain.push(block);
                    }
                } else {
                    remain.push(block);
                }
            });

            if (abort) return false;
            target.ATTR = remain;

            // 属性施加前执行
            target.BEFORE_APPLIED_ATTR_EXECUTE.forEach(block => {
                if (block.duration > 0 && this._isMatchAttrType(block)) {
                    block.Execute(this);
                }
            });

            // 添加到目标数组
            target.ATTR.push(this);
        }

        // 生成战报
        if (needReport) {
            this.InitReport(reportStyle, reportLevel,null,null,doRepeat);
        }

        if(!doRepeat){
            // 属性施加后执行
            target.AFTER_APPLIED_ATTR_EXECUTE.forEach(block => {
                if (block.duration > 0 && this._isMatchAttrType(block)) {
                    block.Execute(this);
                }
            });
        }

        return true;
    }

    /**
     * 私有辅助方法：判断属性类型是否匹配
     * @param {*} block 执行块
     * @returns 
     */
    _isMatchAttrType(block) {
        return (block.isAppliedAd && this.attrType === '攻击') ||
            (block.isAppliedTact && this.attrType === '谋略') ||
            (block.isAppliedDe && this.attrType === '防御') ||
            (block.isAppliedSpeed && this.attrType === '速度');
    }

    /**
     * 重写战报方法：属性块专属战报
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null,doRepeat = false) {
        let report = new Report();
        let msg = `${this.attrType}属性`;
        msg += this.isBenefit ? "提高" : "降低";

        // 准备阶段数值为0的特殊处理
        if (this.owner.driver.turn < 1 && this.value === 0) {
            msg += "效果已经施加";
        } else {
            msg += `${Math.abs(this.value)}(${GetAttr(this.owner, this.attrType)})`;
        }
        if(doRepeat) msg += "（刷新）"

        if (reportStyle === 1 || reportStyle == null) {
            report.InitExecuteReport(reportLevel, this.owner, msg);
        }
        if (reportStyle === 2) {
            report.InitTwoTargetReport(reportLevel, this.applicator, this.owner, `【${this.tactics.name}】令`, msg);
        }
        if (reportStyle === 3) {
            let r = new Report("状态信息");
            r.InitExecuteReport(reportLevel, this.owner, msg + "效果消失了");
        }
        if (reportStyle === 4) {
            report.InitExecuteReport(reportLevel, this.owner, msg + "效果被移除了");
        }
        if (reportStyle === 5) {
            report.InitTwoTargetReport(reportLevel, newApplicator, this.owner, `【${newTact.name}】移除了`, msg + "效果");
        }
    }
}

// ------------------------- 属性块被施加时执行块 --------------------------------------------------
export class AttrAppliedExecuteBlock extends Block {
    /**
     * 属性块被施加时执行块
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} isBeforeApplied 是否施加前执行
     * @param {*} isAppliedAd 是否匹配攻击属性
     * @param {*} isAppliedTact 是否匹配谋略属性
     * @param {*} isAppliedDe 是否匹配防御属性
     * @param {*} isAppliedSpeed 是否匹配速度属性
     * @param {*} execute 执行函数
     * @param {*} duration 持续时间
     */
    constructor(applicator, tactics, isBeforeApplied, isAppliedAd, isAppliedTact, isAppliedDe, isAppliedSpeed, execute, duration) {
        super(applicator, tactics, duration, 0); // 调用父类构造函数
        // 子类自有属性
        this.isBeforeApplied = isBeforeApplied ?? true;
        this.isAfterApplied = !this.isBeforeApplied;
        this.isAppliedAd = isAppliedAd ?? true;
        this.isAppliedTact = isAppliedTact ?? true;
        this.isAppliedDe = isAppliedDe ?? true;
        this.isAppliedSpeed = isAppliedSpeed ?? true;
        this.execute = execute; // 执行函数
        this.attrBlock = null; // 关联的属性块
    }

    /**
     * 初始化执行块
     * @param {*} target 目标武将
     * @returns 
     */
    Init(target) {
        // 绑定目标（存储数组根据执行时机动态指定）
        let storageKey = this.isBeforeApplied ? "BEFORE_APPLIED_ATTR_EXECUTE" : "AFTER_APPLIED_ATTR_EXECUTE";
        super.BindTarget(target, storageKey);

        // 添加到目标数组
        target[storageKey].push(this);
        return true;
    }

    /**
     * 执行绑定的函数
     * @param {*} attrBlock 关联的属性块
     */
    Execute(attrBlock) {
        this.attrBlock = attrBlock;
        this.execute();
    }

    SelfDestroy() {
        return super.SelfDestroy(); 
    }
}

