export class TargetSelectExecuteBlock extends Block {
    /**
     * 选择目标的执行块
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} isBefore 选择目标前/后执行
     * @param {*} execute 执行函数
     * @param {*} duration 持续时间
     */
    constructor(applicator, tactics, isBefore, execute, duration) {
        super(applicator, tactics, duration, 0);
        this.isBefore = isBefore; // 选择目标前/后
        this.whoSelectTarget = null; // 谁在选目标
        this.whichTact = null; // 哪个战法在选目标
        this.range = 0; // 选择范围
        this.tgtNumber = 0; // 目标数量
        this.targetArr = []; // 选中的原始目标数组
        this.finalTargets = [];// 可选的调整后目标数组
        this.forWhat = []; // 选目标的目的
        this.execute = execute; // 执行函数
    }

    /**
     * 初始化块
     * @param {*} target 目标武将
     */
    Init(target) {
        // 动态确定存储数组名称
        let storageKey = this.isBefore
            ? "BEFORE_TARGET_SELECT_EXECUTE"
            : "AFTER_TARGET_SELECT_EXECUTE";
        // 绑定目标和存储数组
        super.BindTarget(target, storageKey);
        // 添加到目标数组
        target[storageKey].push(this);
    }

    /**
     * 执行块逻辑
     * @param {*} whoSelectTarget 选目标的武将
     * @param {*} whichTact 选目标的战法
     * @param {*} range 选择范围
     * @param {*} tgtNumber 目标数量
     * @param {*} targets 选中的目标数组
     * @param {*} forWhat 选目标的目的
     */
    Execute(whoSelectTarget, whichTact, range, tgtNumber, targets, forWhat) {
        this.whoSelectTarget = whoSelectTarget;
        this.whichTact = whichTact;
        this.range = range;
        this.tgtNumber = tgtNumber;
        this.targetArr = targets;
        this.finalTargets = targets;
        this.forWhat = forWhat == "" ? [] : forWhat;
        this.execute();
    }

    SelfDestroy() {
        return super.SelfDestroy(); 
    }
}

