export class ExecuteBlock extends Block {
    /**
     * 普通执行块（指定阶段执行）
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} executeStage 执行阶段
     * @param {*} execute 执行函数
     * @param {*} duration 持续时间
     * @param {*} weight 执行权重（默认1）
     */
    constructor(applicator, tactics, executeStage, execute, duration, weight) {
        // 调用父类构造函数
        super(applicator, tactics, duration, 0);
        // 子类自有属性
        this.executeStage = executeStage; // 执行阶段
        this.execute = execute; // 执行函数
        this.weight = weight ?? 1; // 执行权重
    }

    /**
     * 初始化块（支持优先插入）
     * @param {*} target 目标武将
     * @param {boolean} prior 是否优先执行（默认false）
     * @returns {boolean} 初始化结果
     */
    Init(target, prior = false) {
        // 绑定目标和存储数组
        super.BindTarget(target, "EXECUTE");
        // 优先插入或追加到数组
        prior ? target.EXECUTE.unshift(this) : target.EXECUTE.push(this);
        return true;
    }
}

