// ------------------------- 范围增减益 --------------------------------------------------
export class RangeBlock extends Block {
    /**
     * 范围增减益
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} isCommonAttack 普通攻击/战法距离（默认战法）
     * @param {*} value 增减数值
     * @param {*} duration 持续时间
     * @param {*} waitTime 生效等待时间
     * @param {*} workTactics 作用的指定战法（默认null）
     */
    constructor(applicator, tactics, isCommonAttack, value, duration, waitTime, workTactics) {
        // 有waitTime，传入实际值
        super(applicator, tactics, duration, waitTime);
        // 子类自有属性
        this.isCommonAttack = isCommonAttack; // 普通攻击/战法距离
        this.value = value; // 增减数值
        this.isBenefit = value > 0; // 是否增益
        this.workTactics = workTactics || null; // 作用的指定战法
    }

    Init(target, needReport = true, reportLevel = 3, isRepeat = false, reportStyle = 1) {
        super.BindTarget(target, "RANGE");
        // 冲突检测（非叠加场景）
        if (!isRepeat) {
            let abort = target.RANGE.some(block =>
                block.tactics.type === this.tactics.type && block.isCommonAttack === this.isCommonAttack
            );
            if (abort) {
                let text = this.isCommonAttack ? "已存在攻击距离" : "已存在战法距离";
                let report = new Report();
                if (this.value > 0 && target.RANGE.find(b => b.value > 0)) {
                    text += "提升效果";
                    report.InitExecuteReport(3, target, text);
                } else if (this.value < 0 && target.RANGE.find(b => b.value < 0)) {
                    text += "降低效果";
                    report.InitExecuteReport(3, target, text);
                }
                return false;
            }
        }
        target.RANGE.push(this);
        if (needReport) {
            this.InitReport(reportStyle, reportLevel);
        }
        return true;
    }

    /**
     * 生成战报
     * @param {*} reportStyle 战报样式
     * @param {*} reportLevel 战报等级
     * @param {*} newApplicator 新施加者
     * @param {*} newTact 新战法
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null) {
        let r = new Report();
        let msg = "";
        msg += this.isCommonAttack ? "攻击距离" : "战法距离";
        msg += this.isBenefit ? "提高" : "降低";
        msg += this.isCommonAttack ? `${Math.abs(this.value)}(${GetRange(this.beExecuted)})` : `提高${Math.abs(this.value)}`;

        if (reportStyle === 1) r.InitExecuteReport(reportLevel, this.beExecuted, msg);
        if (reportStyle === 2) r.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】令`, msg);
        if (reportStyle === 3) {
            r = new Report("状态信息");
            r.InitExecuteReport(reportLevel, this.beExecuted, msg + "效果消失了");
        }
        if (reportStyle === 4) r.InitExecuteReport(reportLevel, this.beExecuted, msg + "效果被移除了");
        if (reportStyle === 5 && newApplicator && newTact) {
            r.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, msg + "效果");
        }
    }
}

// ------------------------- 控制战法的发动几率和是否跳过准备阶段 --------------------------------------------------
export class RateBlock extends Block {
    /**
     * 控制战法的发动几率和是否跳过准备阶段
     * @param {*} applicator 施加者
     * @param {*} tactics 来源战法
     * @param {*} workTactics 作用的战法
     * @param {*} value 几率增减数值
     * @param {*} duration 持续时间
     * @param {*} waitTime 生效等待时间
     * @param {*} skipTime 跳过准备时间（默认0）
     */
    constructor(applicator, tactics, workTactics, value, duration, waitTime, skipTime) {
        // 有waitTime，传入实际值
        super(applicator, tactics, duration, waitTime);
        // 子类自有属性
        this.workTactics = workTactics; // 作用的战法
        this.value = value; // 几率增减数值
        this.skipTime = skipTime ?? 0; // 跳过准备时间
        this.isBenefit = this.value > 0 || this.skipTime > 0; // 是否增益
    }

    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        super.BindTarget(target, "RATE_VAR");
        // 冲突检测
        let abort = target.RATE_VAR.some(block =>
            block.tactics.type === this.tactics.type && block.workTactics === this.workTactics
            && block.skipTime == this.skipTime
        );
        if (abort) {
            let r = new Report();
            if (this.skipTime === 0) {
                let txt = `已存在【${this.workTactics.name}】的发动几率${this.value > 0 ? "提高" : "降低"}效果`;
                r.InitExecuteReport(3, target, txt);
            } else if ((this.skipTime > 0 && this.skipTime > 0) || (this.skipTime < 0 && this.skipTime < 0)) {
                let txt = `已存在【${this.workTactics.name}】的准备时间${this.skipTime > 0 ? "增加" : "减少"}${Math.abs(this.skipTime)}回合效果`;
                r.InitExecuteReport(3, target, txt);
            }
            return false;
        }
        target.RATE_VAR.push(this);
        if (needReport) {
            this.InitReport(reportStyle, reportLevel);
        }
        return true;
    }

    /**
     * 生成战报
     * @param {*} reportStyle 战报样式
     * @param {*} reportLevel 战报等级
     * @param {*} newApplicator 新施加者
     * @param {*} newTact 新战法
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null) {
        // 几率变化战报
        if (this.value) {
            let r1 = new Report();
            let msg1 = `【${this.workTactics.name}】发动几率${this.isBenefit ? "提高" : "降低"}`;
            msg1 += this.value ? `${Math.abs(this.value)}%` : "";
            if (this.beExecuted.driver.turn < 1) msg1 += "效果已施加";

            if (reportStyle === 1) r1.InitExecuteReport(reportLevel, this.beExecuted, msg1);
            if (reportStyle === 2) r1.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】令`, msg1);
            if (reportStyle === 3) {
                r1 = new Report("状态信息");
                r1.InitExecuteReport(reportLevel, this.beExecuted, msg1 + "效果消失了");
            }
            if (reportStyle === 4) r1.InitExecuteReport(reportLevel, this.beExecuted, msg1 + "效果被移除了");
            if (reportStyle === 5 && newApplicator && newTact) {
                r1.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, msg1 + "效果");
            }
        }

        // 准备时间变化战报
        if (this.skipTime) {
            let r = new Report();
            let msg = `【${this.workTactics.name}】准备时间${this.isBenefit ? "增加" : "跳过"}`;
            msg += this.skipTime ? `${Math.abs(this.skipTime)}回合` : ``;
            if (this.beExecuted.driver.turn < 1) msg += "效果已施加";

            if (reportStyle === 1) r.InitExecuteReport(reportLevel, this.beExecuted, msg);
            if (reportStyle === 2) r.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】令`, msg);
            if (reportStyle === 3) {
                r = new Report("状态信息");
                r.InitExecuteReport(reportLevel, this.beExecuted, msg + "效果消失了");
            }
            if (reportStyle === 4) r.InitExecuteReport(reportLevel, this.beExecuted, msg + "效果被移除了");
            if (reportStyle === 5 && newApplicator && newTact) {
                r.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, msg + "效果");
            }
        }
    }

    /**
     * 复用父类SelfDestroy，替代原有逻辑
     */
    SelfDestroy() {
        return super.SelfDestroy();
    }
}

