// ------------------------- 状态类型块 --------------------------------------------------
export class StatusBlock extends Block {
    /**
     * 状态类型块
     * @param {object} applicator 施加者
     * @param {object} tactics 来源战法
     * @param {string} type 状态类型
     * @param {number} duration 持续时间
     * @param {number} waitTime 等待时间（默认0）
     * @param {boolean} canRemove 是否可移除（默认true）
     */
    constructor(applicator, tactics, type, duration, waitTime, canRemove) {
        super(applicator, tactics, duration, waitTime ?? 0);
        // 子类自有属性
        this.type = type; // 状态类型
        this.isBenefit = benefitStatus.includes(type); // 是否是增益
        this.canRemove = canRemove ?? true; // 是否可被移除
    }

    /**
     * 初始化
     * @param {object} target 目标武将
     * @param {boolean} needReport 是否需要战报（默认true）
     * @param {number} reportLevel 战报等级（默认3）
     * @param {number} reportStyle 战报样式（默认1）
     * @returns {boolean} 初始化结果
     */
    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        // 绑定目标和存储数组
        super.BindTarget(target, "STATUS");
        this.beExecuted = target;

        // 免疫检查
        if (IsGetStatus(target, `免疫${this.type}`)) {
            let report = new Report();
            report.InitExecuteReport(3, target, `免疫${this.type}`);
            return false;
        }

        // 检查抵御效果(指挥战法阶段不进行抵御)
        if (target.driver.turn >= 1) {
            let resistWork = target.STATUS_RESIST.some(block => {
                if (block.resistType === this.type) {
                    let rand = Math.floor(Math.random() * 100);
                    let realOdd = GetMoraleRate(target, block.rate);
                    if (rand < realOdd) {
                        let r = new Report();
                        r.InitTwoTargetReport(3, block.applicator, target, `【${block.tactics.name}】令`, `抵御了${this.type}状态`);
                        return true;
                    } else {
                        let r = new Report("触发概率");
                        r.InitExecuteReport(3, block.applicator, `【${block.tactics.name}】的抵御效果没有生效，生效几率为${realOdd}%`);
                    }
                }
            });
            if (resistWork) return false;
        }

        // 执行即将陷入特殊状态时执行块
        target.BEFORE_FALL_INTO_STATUS.forEach(block => {
            block.GetData(this.applicator, this.tactics, this.type, this.duration, this.isBenefit, this.waitTime, this);
            block.Execute();
        });

        // 检查冲突
        let abort = target.STATUS.some(block => {
            // 找到同类型效果，冲突（只考虑类型，不考虑战法类型）
            if (block.type === this.type && this.type !== '无法普通攻击' && this.type !== '无法施法') {
                let report = new Report();
                report.InitExecuteReport(3, target, `已存在${block.type}效果`);
                return true;
            }
        });
        if (abort) return false;

        target.STATUS.push(this);

        // 生成战报
        if (needReport) {
            this.InitReport(reportStyle, reportLevel);
        }

        // 执行特殊状态时执行块
        target.FALL_INTO_STATUS.forEach(block => {
            block.GetData(this.applicator, this.tactics, this.type, this.duration, this.isBenefit, this.waitTime, this);
            block.Execute();
        });

        return true;
    }

    /**
     * 生成战报
     * @param {number} reportStyle 战报样式（1-5）
     * @param {number} reportLevel 战报等级
     * @param {object} newApplicator 新施加者（用于移除类战报）
     * @param {object} newTact 新战法（用于移除类战报）
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null) {
        let msg = "";
        if (['怯战', '犹豫', '混乱', '暴走'].includes(this.type)) {
            if (this.beExecuted.driver.turn > 0 && this.waitTime <= 0) msg = `陷入${this.type}中`;
            else msg = `${this.type}`;
        } else if (this.type === "同心" || this.type == "连击") {
            msg = `进入${this.type}状态`;
        } else if (this.type === "围困") {
            msg = `不可回复兵力`;
        } else if (["先手", "洞察"].includes(this.type)) {
            msg = `获得${this.type}`;
        } else if (['挑衅', '援护'].includes(this.type)) {
            msg = `受到${this.type}`;
        } else if (this.type === '无视兵种') {
            msg = `无视兵种相克`;
        } else if (['不受指挥战法影响', '不受敌方指挥战法影响'].includes(this.type)) {
            msg = `${this.type}`;
        } else {
            msg = `${this.type}`;
        }

        if (this.waitTime > 0 || this.beExecuted.driver.turn < 1) msg += "(预备)";
        if (reportStyle === 1 && this.beExecuted.driver.turn < 1) msg += "效果已施加";

        let r = new Report();
        switch (reportStyle) {
            case 1:
                r.InitExecuteReport(reportLevel, this.beExecuted, msg);
                break;
            case 2:
                r.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】令`, msg);
                break;
            case 3: {
                let r = new Report("状态信息");
                r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}状态消失了`);
                break;
            }
            case 4:
                r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}状态被移除了`);
                break;
            case 5:
                r.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, `${this.type}状态`);
                break;
        }
    }
}

// ------------------------- 伤害型状态块 --------------------------------------------------
export class DamageStatusBlock extends Block {
    /**
     * 伤害型状态
     * @param {object} applicator 施加者
     * @param {object} tactics 来源战法
     * @param {string} type 状态类型：恐慌，妖术，火攻，燃烧，动摇
     * @param {Object} dmgInstance 伤害实例
     * @param {number} duration 持续时间
     * @param {number} waitTime 等待时间（默认0）
     * @param {boolean} isExecute 是否执行效果（默认true）
     * @param {boolean} canRemove 是否可移除（默认true）
     * @param {Function} callBack 回调函数（默认null）
     * @param {string} callTime 回调时机（默认"行动开始"）
     */
    constructor(applicator, tactics, type, dmgInstance, duration, waitTime, isExecute, canRemove, callBack, callTime) {
        // 有waitTime，传入实际值（默认0）
        super(applicator, tactics, duration, waitTime ?? 0);
        // 子类自有属性
        this.type = type; // 状态类型
        this.dmgInstance = dmgInstance; // 伤害实例
        this.isExecute = isExecute ?? true; // 是否执行效果
        this.canRemove = canRemove ?? true; // 是否可移除
        this.callBack = callBack ?? null; // 回调函数
        this.callTime = callTime ?? "行动开始"; // 回调时机
    }

    /**
     * 初始化
     * @param {object} target 目标武将
     * @param {boolean} needReport 是否需要战报（默认true）
     * @param {number} reportLevel 战报等级（默认3）
     * @param {number} reportStyle 战报样式（默认1）
     * @returns {boolean} 初始化结果
     */
    Init(target, needReport = true, reportLevel = 3, reportStyle = 1) {
        // 绑定目标和存储数组
        super.BindTarget(target, "SPECIAL_STATUS");
        this.beExecuted = target;

        // 冲突判定
        let refresh = false;
        let remain = [];
        let abort = target.SPECIAL_STATUS.some(block => {
            if (block.tactics.type === this.tactics.type && block.type === this.type) {
                if (block.dmgInstance.dmgValue >= this.dmgInstance.dmgValue) {
                    let r = new Report();
                    let text = block.dmgInstance.dmgValue > this.dmgInstance.dmgValue
                        ? `已存在更强的${this.type}效果`
                        : `已存在相同的${this.type}效果`;
                    r.InitExecuteReport(reportLevel, target, text);
                    return true;
                } else {
                    let r = new Report();
                    r.InitExecuteReport(reportLevel, target, `${this.type}效果刷新了`);
                    refresh = true;
                }
            } else {
                remain.push(block);
            }
        });

        if (abort) return false;

        target.SPECIAL_STATUS = remain;
        target.SPECIAL_STATUS.push(this);

        // 生成战报（刷新时不生成）
        if (needReport && !refresh) {
            this.InitReport(reportStyle, reportLevel);
        }

        // 执行陷入持续伤害块
        target.FALL_INTO_CONTINUE_DAMAGE.forEach(block => {
            block.GetData(this.type, this.dmgInstance.dmgType, this.dmgInstance.dmgValue, this.applicator, this.tactics, this.duration, this);
            block.Execute();
        });

        return true;
    }

    /**
     * 生成战报
     * @param {number} reportStyle 战报样式（1-5）
     * @param {number} reportLevel 战报等级
     * @param {object} newApplicator 新施加者（用于移除类战报）
     * @param {object} newTact 新战法（用于移除类战报）
     */
    InitReport(reportStyle = 1, reportLevel = 3, newApplicator = null, newTact = null) {
        let r = new Report();
        let msg = `${this.type}`;
        if (this.waitTime > 0) msg += "(预备)";
        msg += "效果已施加";

        switch (reportStyle) {
            case 1:
                r.InitExecuteReport(reportLevel, this.beExecuted, msg);
                break;
            case 2:
                r.InitTwoTargetReport(reportLevel, this.applicator, this.beExecuted, `【${this.tactics.name}】对`, `施加了${this.type}效果`);
                break;
            case 3: {
                let r = new Report("状态信息");
                r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}效果消失了`);
                break;
            }
            case 4:
                r.InitExecuteReport(reportLevel, this.beExecuted, `【${this.tactics.name}】施加的${this.type}效果被移除了`);
                break;
            case 5:
                r.InitTwoTargetReport(reportLevel, newApplicator, this.beExecuted, `【${newTact.name}】移除了`, `的${this.type}效果`);
                break;
        }
    }

    /**
     * 状态伤害触发执行
     * @param {object} target 目标武将
     * @param {boolean} isByTrigger 是否由触发器触发（影响战报等级）
     */
    Execute(target, isByTrigger = false) {
        let rpLevel = isByTrigger ? 3 : 2;
        Hurt(this.applicator, target, this.dmgInstance, true, 3, rpLevel);

        // 执行回调函数
        if (typeof this.callBack === 'function') {
            this.callBack();
        }
    }
}

